css:
:host {
  --bg: #f6f1e8;
  --bg-top: #fbf7f0;
  --bg-mid: #f5ebdb;
  --bg-bottom: #efe2ce;
  --surface: rgba(255, 255, 255, 0.94);
  --surface-soft: #fffaf2;
  --ink: #1f2937;
  --muted: #5f6b7a;
  --line: rgba(15, 23, 42, 0.08);
  --brand: #083f3d;
  --brand-2: #0d7a6c;
  --accent: #d97706;
  --copper: #9a5c00;
  --sand: rgba(255, 252, 246, 0.92);
  --danger: #b91c1c;
  --danger-bg: #fff1f2;
  --shadow: 0 26px 70px rgba(15, 23, 42, 0.12);
  --shadow-soft: 0 14px 30px rgba(15, 23, 42, 0.08);
  --radius: 16px;
  --radius-lg: 30px;
  --font: "Manrope", "Aptos", "Segoe UI", "Helvetica Neue", sans-serif;
  --display-font: "Fraunces", "Georgia", serif;
}
/* Shared training-style navigation cards across the ecosystem. */
.module-link-card,
.return-strip a {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-width: 0;
  min-height: 0;
  padding: 10px 2px;
  border: 1px solid #e2e6df;
  border-radius: 15px;
  background: #fff;
  color: #12324f;
  text-decoration: none;
  box-shadow: none;
  font-size: clamp(.58rem, 2vw, .85rem);
  font-weight: 800;
  transition: transform 140ms ease, filter 140ms ease, box-shadow 140ms ease;
}

.module-link-card::before { display: none; }

.module-link-card__image,
.return-strip img {
  display: block;
  width: 40px;
  height: 40px;
  object-fit: contain;
}

.module-link-card span,
.return-strip span {
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: #12324f;
  font-size: inherit;
  font-weight: inherit;
  letter-spacing: normal;
  line-height: 1.15;
  text-align: center;
}

.module-link-card:hover,
.module-link-card:focus-visible,
.return-strip a:hover,
.return-strip a:focus-visible {
  filter: brightness(1.02);
  transform: translateY(-2px);
  box-shadow: 0 6px 14px rgba(26, 73, 98, .14);
}

.module-link-card:active,
.return-strip a:active {
  transform: translateY(1px) scale(.97);
}

/* Navegação premium: cartões separados, flutuantes e consistentes com Checklist. */
.module-link-strip { gap: 7px; padding: 7px; border-radius: 20px; background: linear-gradient(145deg, rgba(255,255,255,.9), rgba(218,232,239,.72)); box-shadow: 0 14px 26px rgba(8,18,31,.14), inset 0 1px 0 rgba(255,255,255,.96); }
.module-link-strip a { position: relative; isolation: isolate; min-height: 84px; padding: 5px 3px 7px; overflow: hidden; border: 2px solid rgba(255,255,255,.96); border-radius: 16px; background: linear-gradient(145deg, #fff, #e4eef3 56%, #b8d0dc); box-shadow: 0 6px 0 #7898a8, 0 12px 18px rgba(26,73,98,.16), inset 0 1px 0 #fff; transition: transform 150ms ease, filter 150ms ease, box-shadow 150ms ease; }
.module-link-strip a::before { content: ""; position: absolute; z-index: -1; inset: -35% -25% auto; height: 65%; border-radius: 50%; background: linear-gradient(105deg, transparent 18%, rgba(255,255,255,.86) 50%, transparent 82%); transform: rotate(-8deg); pointer-events: none; }
.module-link-strip a:nth-child(2) { background: linear-gradient(145deg, #f5fffd, #cbe9e2 58%, #91c6bb); box-shadow: 0 6px 0 #4c8f88, 0 12px 18px rgba(30,96,89,.16), inset 0 1px 0 #fff; }
.module-link-strip a:nth-child(3) { background: linear-gradient(145deg, #fffdf5, #f3e5c5 58%, #d8b879); box-shadow: 0 6px 0 #9a6b28, 0 12px 18px rgba(154,107,40,.16), inset 0 1px 0 #fff; }
.module-link-strip a:hover, .module-link-strip a:focus-visible { filter: saturate(1.08) brightness(1.03); transform: translateY(-2px); box-shadow: 0 8px 0 #7898a8, 0 17px 24px rgba(26,73,98,.2), inset 0 1px 0 #fff; }
.module-link-strip a:active { transform: translateY(4px) scale(.98); box-shadow: 0 2px 0 #7898a8, 0 6px 10px rgba(26,73,98,.14), inset 0 2px 4px rgba(13,50,87,.12); }
.module-link-strip img { width: min(100%, 56px); height: 52px; }
.module-link-strip span { padding: 2px 4px; border: 1px solid rgba(23,98,161,.2); border-radius: 999px; background: rgba(255,255,255,.68); color: #12324f; font-size: .5rem; line-height: 1; }
@media (max-width: 380px) { .module-link-strip { gap: 4px; padding: 5px; } .module-link-strip a { min-height: 72px; border-radius: 13px; } .module-link-strip img { height: 45px; } }

/* Reports use the same premium record cards as EVENTOS. */
.record-card {
  display: grid;
  grid-template-columns: 27px minmax(0, 1fr);
  gap: 9px;
  padding: 10px;
  border: 1px solid rgba(13, 50, 87, 0.08);
  border-radius: 18px;
  box-shadow: 0 10px 18px rgba(8, 18, 31, 0.06);
  cursor: pointer;
}

.record-card:focus-visible {
  outline: 2px solid rgba(24, 183, 183, 0.36);
  outline-offset: 2px;
}

.record-card--tone-1 { background: rgba(236, 246, 252, 0.92); }
.record-card--tone-2 { background: rgba(245, 242, 255, 0.92); }
.record-card--tone-3 { background: rgba(243, 251, 240, 0.92); }
.record-card--tone-4 { background: rgba(255, 246, 235, 0.92); }

.record-card__number {
  display: grid;
  place-items: center;
  width: 25px;
  height: 25px;
  border-radius: 9px;
  background: var(--brand);
  color: #fff;
  font-size: 0.72rem;
  font-weight: 950;
}

.record-card__rows {
  display: grid;
  gap: 5px;
  min-width: 0;
}

.record-card__row {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  width: 100%;
  box-sizing: border-box;
  gap: 8px;
  padding: 6px 8px;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.62);
  border: 1px solid rgba(47, 114, 106, 0.12);
}

.record-card__row--history {
  display: grid;
  gap: 6px;
  background: linear-gradient(180deg, rgba(255, 244, 207, 0.98), rgba(255, 231, 168, 0.9));
  border: 1px solid rgba(155, 91, 0, 0.18);
}

.record-card__row--registration {
  background: rgba(226, 241, 252, 0.82);
  border: 1px solid rgba(55, 133, 190, 0.18);
}

.record-card__label {
  flex: 0 0 118px;
  min-width: 0;
  color: rgba(20, 50, 84, 0.72);
  font-size: 0.55rem;
  font-weight: 900;
  text-transform: uppercase;
}

.record-card__label--history { color: #9b5b00; }
.record-card__label--registration { color: #397eae; }

.record-card__value,
.record-card__row--registration > span:last-child {
  flex: 1 1 auto;
  min-width: 0;
  color: var(--ink);
  font-size: 0.63rem;
  font-weight: 700;
  line-height: 1.35;
  text-align: right;
  overflow-wrap: anywhere;
}

.record-card__row--registration > span:last-child {
  color: #397eae;
  font-weight: 800;
}

.record-card__history {
  display: grid;
  gap: 6px;
  width: 100%;
}

.record-card__history-entry {
  display: grid;
  gap: 4px;
  padding: 0;
  border: 0;
  background: transparent;
}

.record-card__history-entry + .record-card__history-entry {
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px solid rgba(217, 119, 6, 0.24);
}

.record-card__history-line {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
}

.record-card__history-label {
  flex: 0 0 82px;
  min-width: 0;
  color: #9b5b00;
  font-size: 0.5rem;
  font-weight: 900;
  letter-spacing: 0.02em;
  text-transform: uppercase;
}

.record-card__history-value {
  flex: 1 1 auto;
  min-width: 0;
  color: #743300;
  font-size: 0.58rem;
  font-weight: 800;
  line-height: 1.3;
  overflow-wrap: anywhere;
  text-align: right;
}

.record-card__actions {
  display: flex;
  justify-content: flex-end;
  margin-top: 5px;
}

.summary-list .record-card,
.monthly-list .record-card {
  display: grid !important;
  grid-template-columns: minmax(0, 1fr) !important;
  align-items: start;
}

.summary-list .record-card__number,
.monthly-list .record-card__number {
  grid-column: 1;
  width: fit-content;
  min-width: 20px;
  height: 18px;
  padding: 0 6px;
  border-radius: 7px;
  font-size: 0.58rem;
  line-height: 1;
}

.summary-list .record-card__rows,
.monthly-list .record-card__rows {
  grid-column: 1;
}

.summary-list .record-card__rows,
.monthly-list .record-card__rows {
  display: grid !important;
  grid-template-columns: minmax(0, 1fr) !important;
  width: 100%;
  min-width: 0;
}

.summary-list .record-card__row,
.monthly-list .record-card__row {
  display: flex !important;
  grid-column: 1 / -1;
  min-width: 0;
}

.record-card__edit-button {
  min-height: 34px;
  padding: 7px 13px;
  border: 1px solid rgba(13, 122, 108, 0.3);
  border-radius: 999px;
  background: linear-gradient(135deg, #e9fbf5, #c9eee2);
  color: #0d695d;
  box-shadow: 0 4px 10px rgba(13, 122, 108, 0.16), inset 0 1px 0 rgba(255, 255, 255, 0.8);
  font: inherit;
  font-size: 0.68rem;
  font-weight: 950;
  letter-spacing: 0.04em;
  cursor: pointer;
  touch-action: manipulation;
}

.record-card__edit-button:active { transform: translateY(1px) scale(0.99); }

.record-card .summary-edit-block {
  grid-column: auto;
  width: auto;
  margin: 0;
}

.record-card .summary-edit-entry {
  white-space: normal;
  overflow: visible;
  overflow-wrap: anywhere;
  word-break: break-word;
}

/* Match the EVENTOS report modal shell and data spacing. */
.summary-panel .records-hero,
.monthly-panel .records-hero {
  display: grid;
  justify-items: center;
  width: 100%;
  box-sizing: border-box;
  gap: 3px;
  margin: 0 0 8px;
  padding: 8px 10px 10px;
  border-radius: 18px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.72), rgba(255, 248, 233, 0.58));
  border: 1px solid rgba(199, 154, 62, 0.24);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.84), 0 10px 22px rgba(140, 85, 23, 0.08);
  text-align: center;
}

.summary-panel .records-hero .section-title-copy,
.monthly-panel .records-hero .section-title-copy {
  display: grid;
  justify-items: center;
  width: 100%;
  gap: 3px;
  text-align: center;
}

.summary-panel .records-hero__title,
.monthly-panel .records-hero__title {
  display: block;
  width: 100%;
  margin: 0;
  color: #8c5517;
  font-size: 1rem;
  font-weight: 900;
  line-height: 1.02;
  letter-spacing: 0.04em;
  text-align: center;
  text-shadow: 0 1px 0 rgba(255, 255, 255, 0.62), 0 10px 18px rgba(140, 85, 23, 0.12);
}

.summary-panel .records-hero > [data-auth-user],
.monthly-panel .records-hero > [data-auth-user] {
  color: rgba(20, 50, 84, 0.52);
  font-size: 0.67rem;
  font-weight: 700;
  line-height: 1.15;
}

.summary-panel .records-hero > [data-auth-user]::before,
.monthly-panel .records-hero > [data-auth-user]::before {
  content: "Responsável pelo registro: ";
  color: rgba(20, 50, 84, 0.68);
}

.summary-panel .records-banner {
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr);
  min-height: 0;
  margin-top: 0;
  padding: 12px;
  border-radius: 22px;
  background: linear-gradient(180deg, rgba(255, 252, 246, 0.82), rgba(247, 237, 220, 0.72));
  border: 1px solid rgba(199, 154, 62, 0.22);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.7);
}

.summary-panel .date-field,
.summary-panel .summary-date-field {
  display: grid;
  gap: 4px;
  width: 100%;
  margin: 0;
  color: rgba(20, 50, 84, 0.72);
  font-size: 0.55rem;
  font-weight: 700;
  text-align: center;
}

.summary-panel .date-field input,
.summary-panel .summary-date-field input {
  display: block;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  min-height: 44px;
  box-sizing: border-box;
  border: 2px solid rgba(23, 98, 161, 0.56);
  border-radius: 12px;
  outline: 1px solid rgba(255, 255, 255, 0.72);
  background: rgba(218, 232, 241, 0.9);
  color: var(--ink);
  text-align: center;
}

.summary-panel .date-field input::-webkit-datetime-edit,
.summary-panel .summary-date-field input::-webkit-datetime-edit {
  text-align: center;
}

@media (max-width: 680px) {
  .summary-panel .records-hero,
  .monthly-panel .records-hero {
    margin-bottom: 4px;
    padding: 6px 8px 8px;
  }

  .summary-panel .records-hero__title,
  .monthly-panel .records-hero__title {
    font-size: 0.88rem;
  }

  .summary-panel .records-banner {
    padding: 8px;
    border-radius: 16px;
  }
}

@media (max-width: 680px) {
  .record-card {
    grid-template-columns: 25px minmax(0, 1fr);
    gap: 8px;
    padding: 8px;
  }

  .record-card__label {
    flex-basis: 96px;
    font-size: 0.5rem;
  }

  .record-card__value,
  .record-card__row--registration > span:last-child {
    font-size: 0.59rem;
  }
}

* {
  box-sizing: border-box;
}

:host,[data-module-body] {
  width: 100%;
  max-width: 100%;
  height: 100%;
  overflow: hidden;
  overflow-x: hidden;
  scrollbar-gutter: stable;
  overscroll-behavior: none;
}

[data-module-body] {
  margin: 0;
  min-height: 100dvh;
  font-family: var(--font);
  color: var(--ink);
  background:
    radial-gradient(circle at top left, rgba(217, 119, 6, 0.14), transparent 24%),
    radial-gradient(circle at top right, rgba(13, 122, 108, 0.16), transparent 28%),
    linear-gradient(160deg, var(--bg-top) 0%, var(--bg-bottom) 100%);
  -webkit-text-size-adjust: 100%;
}

.app-shell {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  height: 100dvh;
  max-height: 100dvh;
  overflow: hidden;
}

[data-module-body].modal-open {
  overflow: hidden;
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100dvh;
  scrollbar-gutter: stable;
}

[data-module-body].modal-open::after {
  content: "";
  position: fixed;
  inset: 0;
  z-index: 30;
  pointer-events: none;
  background: rgba(8, 18, 31, 0.56);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}

[data-module-body]::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.33) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.28) 1px, transparent 1px);
  background-size: 28px 28px;
  mask-image: linear-gradient(to bottom, rgba(0, 0, 0, 0.38), transparent 82%);
  -webkit-mask-image: linear-gradient(to bottom, rgba(0, 0, 0, 0.38), transparent 82%);
}

.app-shell {
  position: relative;
  width: min(1120px, calc(100% - 20px));
  margin: 0 auto;
  padding:
    max(6px, env(safe-area-inset-top, 0px))
    0
    max(16px, env(safe-area-inset-bottom, 0px));
}

.topbar {
  position: relative;
  display: grid;
  grid-template-columns: minmax(118px, auto) minmax(0, 1fr) minmax(68px, auto);
  align-items: center;
  justify-items: stretch;
  gap: 4px 8px;
  overflow: hidden;
  margin-bottom: 5px;
  min-height: 0;
  padding: 18px 16px;
  border: 2px solid rgba(255, 159, 67, 0.72);
  border-radius: 24px;
  background: linear-gradient(90deg, rgba(255, 210, 120, 0.4) 0%, rgba(232, 217, 187, 0.96) 100%);
  box-shadow: 0 22px 40px rgba(181, 100, 4, 0.22);
  text-align: left;
  backdrop-filter: blur(18px);
}

.topbar::after {
  content: none;
}

.topbar-status {
  display: flex;
  flex-wrap: wrap;
  grid-column: 3;
  grid-row: 1;
  width: 100%;
  min-width: min(68px, 16vw);
  justify-content: flex-end;
  gap: 5px;
  position: relative;
  z-index: 1;
  margin: 0;
}

.home-logo-link {
  position: relative;
  z-index: 1;
  width: 118px;
  height: 118px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: transparent;
  box-shadow: none;
  text-decoration: none;
  transition: transform 0.18s ease, box-shadow 0.18s ease, filter 0.18s ease;
  -webkit-tap-highlight-color: transparent;
}

.home-logo-link::after {
  content: none;
}

.home-logo-link:hover,
.home-logo-link:focus-visible {
  box-shadow: none;
  filter: saturate(1.05);
  transform: translateY(-1px) scale(1.015);
}

.home-logo-link:active {
  transform: translateY(1px) scale(0.99);
}

.home-logo-image {
  width: 100%;
  height: 100%;
  object-fit: contain;
  filter: drop-shadow(0 12px 24px rgba(15, 23, 42, 0.14));
}

.home-logo-label {
  position: absolute;
  z-index: 2;
  right: 8px;
  bottom: 4px;
  left: 8px;
  padding: 2px 4px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.92);
  color: #1762a1;
  font-size: 0.58rem;
  font-weight: 900;
  letter-spacing: 0.12em;
  line-height: 1.1;
  text-align: center;
}

/* Premium 3D logo button for the title. */
.home-logo-link {
  position: relative;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.95);
  background: linear-gradient(145deg, #ffffff 0%, #e8f2f7 52%, #b9d0dc 100%);
  box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.48), 0 16px 28px rgba(12, 49, 72, 0.26), inset 0 2px 0 rgba(255, 255, 255, 0.98), inset 0 -8px 14px rgba(37, 78, 101, 0.14);
  transition: transform 160ms ease, filter 160ms ease, box-shadow 160ms ease;
}

.home-logo-link::before {
  content: "";
  position: absolute;
  inset: -35% -20% auto;
  height: 58%;
  border-radius: 50%;
  background: linear-gradient(100deg, transparent 12%, rgba(255, 255, 255, 0.82) 50%, transparent 86%);
  transform: rotate(-10deg);
  pointer-events: none;
}

.home-logo-link:hover,
.home-logo-link:focus-visible {
  filter: saturate(1.08);
  transform: translateY(-2px) scale(1.015);
}

.home-logo-link:active {
  transform: translateY(1px) scale(0.98);
}

.home-logo-image {
  position: relative;
  z-index: 1;
  filter: drop-shadow(0 8px 9px rgba(20, 52, 75, 0.2));
}

.hero-copy {
  position: relative;
  z-index: 1;
  min-width: 0;
  grid-column: 2;
  justify-self: center;
  display: grid;
  justify-items: center;
  text-align: center;
}

.hero-copy h1 {
  font-family: var(--display-font);
  color: var(--ink);
  font-size: clamp(0.94rem, 3.4vw, 1.34rem);
  font-weight: 700;
  line-height: 1.05;
  letter-spacing: -0.02em;
  text-shadow: none;
}

.eyebrow {
  display: inline-block;
  margin-bottom: 6px;
  color: var(--brand-2);
  font-size: 0.78rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

h1,
h2 {
  margin: 0;
  letter-spacing: -0.04em;
}

h1 {
  font-size: clamp(2.15rem, 8vw, 4.2rem);
  line-height: 0.88;
}

h2 {
  font-size: 1.08rem;
}

.layout {
  display: grid;
  gap: 12px;
  min-height: 100%;
  align-content: start;
}

.scanner-panel {
  order: 1;
  margin: 6px 0 8px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-height: 0;
  border-color: rgba(13, 122, 108, 0.22);
  background:
    radial-gradient(circle at 15% 0%, rgba(13, 122, 108, 0.13), transparent 32%),
    linear-gradient(145deg, rgba(255, 255, 255, 0.98), rgba(248, 243, 232, 0.94));
  box-shadow:
    0 30px 70px rgba(8, 63, 61, 0.14),
    inset 0 0 0 1px rgba(255, 255, 255, 0.62);
}

.form-panel {
  order: 2;
}

.form-panel[hidden],
.summary-panel[hidden],
.monthly-panel[hidden],
.monthly-report-panel[hidden],
.modal-panel[hidden] {
  display: none !important;
}

label[hidden] {
  display: none !important;
}

.form-panel.is-open,
.summary-panel.is-open,
.monthly-panel.is-open,
.monthly-report-panel.is-open {
  animation: panel-arrival 260ms ease both;
}

.summary-panel {
  order: 3;
}

.summary-panel.modal-panel {
  display: grid;
  grid-template-rows: auto auto auto minmax(0, 1fr) auto;
  align-content: start;
  max-height: calc(100dvh - 12px);
}

.monthly-panel {
  order: 4;
}

.monthly-panel.modal-panel {
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr) auto auto;
  align-content: start;
  max-height: calc(100dvh - 12px);
}

.monthly-heading {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 8px;
  align-items: center;
  margin-bottom: 7px;
}

.monthly-heading::before {
  content: none !important;
}

