label {
  display: grid;
  gap: 8px;
  padding: 12px;
  border: 1px solid rgba(15, 23, 42, 0.05);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.74);
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.45),
    0 12px 24px rgba(15, 23, 42, 0.05);
  font-weight: 760;
  transition: box-shadow 140ms ease, transform 140ms ease, border-color 140ms ease;
}

label:focus-within {
  border-color: rgba(13, 122, 108, 0.22);
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.45),
    0 0 0 3px rgba(13, 122, 108, 0.12),
    0 12px 24px rgba(15, 23, 42, 0.05);
}

label span {
  color: var(--brand);
  font-size: 0.7rem;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

small,
.hint {
  color: var(--muted);
  font-size: 0.82rem;
  font-weight: 500;
  line-height: 1.4;
}

.hint {
  margin: 7px 2px 0;
}

.hint[data-tone="success"] {
  color: #166534;
}

.hint[data-tone="error"] {
  color: var(--danger);
}

input,
textarea,
select {
  width: 100%;
  min-height: 50px;
  border: 0;
  outline: 0;
  border-radius: 12px;
  padding: 12px 13px;
  font: inherit;
  color: var(--ink);
  background: rgba(255, 255, 255, 0.94);
  box-shadow: inset 0 0 0 1px rgba(15, 23, 42, 0.06);
  font-size: 16px;
}

.native-multi-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
  pointer-events: none;
}

.multi-select {
  position: relative;
}

.multi-select-toggle {
  width: 100%;
  min-height: 48px;
  border: 1px solid var(--line);
  background: white;
  color: var(--muted);
  text-align: left;
  font-weight: 750;
}

.multi-select-toggle::after {
  content: "";
  float: right;
  color: var(--brand-2);
  font-size: 0.74rem;
  font-weight: 900;
  letter-spacing: 0.02em;
  text-transform: uppercase;
}

.multi-select-toggle.has-selection {
  color: var(--ink);
  background: #fffaf0;
  border-color: rgba(217, 154, 36, 0.7);
}

.multi-select-options {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
  margin-top: 8px;
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: white;
  box-shadow: 0 16px 30px rgba(12, 35, 31, 0.1);
}

.form-panel .multi-select-options {
  position: static;
  left: auto;
  right: auto;
  bottom: auto;
  z-index: 1;
  max-height: min(28dvh, 220px);
  overflow-y: auto;
  padding: 12px;
  border-color: rgba(13, 122, 108, 0.22);
  border-radius: 22px;
  background:
    radial-gradient(circle at top left, rgba(217, 119, 6, 0.1), transparent 30%),
    linear-gradient(145deg, rgba(255, 255, 255, 0.98), rgba(250, 246, 238, 0.98));
  box-shadow:
    0 26px 60px rgba(15, 23, 42, 0.22),
    inset 0 0 0 1px rgba(255, 255, 255, 0.7);
}

.multi-select-options[hidden] {
  display: none;
}

.multi-select-options label {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 42px;
  padding: 8px;
  border: 1px solid #e4ece7;
  border-radius: 7px;
  background: #f8faf7;
  font-weight: 850;
}

.multi-select-options input {
  width: auto;
  accent-color: var(--brand);
}

textarea {
  resize: vertical;
}

.full-width {
  grid-column: 1 / -1;
}

.summary-tools {
  align-items: end;
  margin-top: 0;
}

.summary-tools label {
  min-width: 180px;
  flex: 1 1 180px;
}

.monthly-status {
  margin: 8px 0 0;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface-soft);
  color: var(--muted);
  font-size: 0.86rem;
  font-weight: 800;
}

.monthly-status[data-tone="success"] {
  border-color: rgba(22, 101, 52, 0.24);
  background: rgba(220, 252, 231, 0.68);
  color: #166534;
}

.monthly-status[data-tone="error"] {
  border-color: rgba(185, 28, 28, 0.24);
  background: var(--danger-bg);
  color: var(--danger);
}

.monthly-report-panel {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  gap: 8px;
  margin-top: 6px;
  padding: 8px;
  border: 1px solid rgba(15, 23, 42, 0.05);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.58);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.42);
  min-height: 0;
  overflow: hidden;
}

.monthly-list {
  min-height: 0;
  max-height: none;
  overflow-y: auto;
  padding: 2px 2px 6px 0;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
}

.monthly-records {
  display: grid;
  gap: 9px;
}

.monthly-record-card {
  display: grid;
  grid-template-columns: 27px minmax(0, 1fr);
  gap: 9px;
  padding: 10px 11px;
  border: 1px solid rgba(47, 114, 106, 0.16);
  border-radius: 15px;
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.98), rgba(239, 248, 244, 0.88));
  box-shadow: 0 8px 18px rgba(15, 77, 68, 0.07);
}

.monthly-table-card {
  border-radius: 18px;
  box-shadow:
    0 12px 24px rgba(13, 50, 87, 0.08),
    inset 0 0 0 1px rgba(255, 255, 255, 0.42);
}

.monthly-tone-a {
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.98), rgba(237, 244, 249, 0.92));
}

.monthly-tone-b {
  background: linear-gradient(135deg, rgba(250, 252, 255, 0.98), rgba(228, 239, 247, 0.9));
}

.monthly-record-number {
  display: grid;
  place-items: center;
  width: 25px;
  height: 25px;
  border-radius: 9px;
  background: var(--brand);
  color: #fff;
  font-size: 0.72rem;
  font-weight: 950;
}

.monthly-record-fields {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.monthly-record-fields > div {
  display: grid;
  grid-template-columns: minmax(108px, 0.42fr) minmax(0, 1fr);
  gap: 8px;
  align-items: baseline;
  padding-bottom: 3px;
  border-bottom: 1px solid rgba(15, 77, 68, 0.08);
}

.monthly-record-fields > div:last-child {
  border-bottom: 0;
  padding-bottom: 0;
}

.monthly-record-fields span {
  color: var(--muted);
  font-size: 0.66rem;
  font-weight: 950;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.monthly-record-fields strong {
  min-width: 0;
  overflow-wrap: anywhere;
  color: #173f3b;
  font-size: 0.8rem;
  line-height: 1.22;
}

.monthly-table-wrap {
  overflow-x: auto;
  border: 1px solid rgba(15, 23, 42, 0.07);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.86);
  box-shadow: 0 14px 24px rgba(15, 23, 42, 0.06);
}

.monthly-table {
  width: 100%;
  min-width: 920px;
  border-collapse: collapse;
  font-size: 0.78rem;
}

.monthly-table th,
.monthly-table td {
  padding: 9px 10px;
  border-bottom: 1px solid rgba(15, 23, 42, 0.06);
  text-align: left;
  vertical-align: top;
}

.monthly-table th {
  position: sticky;
  top: 0;
  z-index: 1;
  background: #edf6f2;
  color: var(--brand);
  font-size: 0.68rem;
  font-weight: 950;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.monthly-table tbody tr:nth-child(even) {
  background: rgba(248, 250, 246, 0.72);
}

.monthly-table tr.alert-row {
  background: #fff1f2;
  color: var(--danger);
  font-weight: 850;
}

.monthly-whatsapp-button {
  margin-top: 2px;
}

.summary-date-picker {
  display: grid;
  gap: 7px;
  margin: 0;
  color: var(--muted);
  font-size: 0.82rem;
  font-weight: 900;
  text-transform: uppercase;
}

.summary-date-picker input {
  min-height: 44px;
  padding: 0 12px;
  text-transform: none;
}

.summary-search-box {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(152px, 0.95fr) auto;
  gap: 8px;
  align-items: stretch;
}

.summary-search-title {
  display: block;
  margin-bottom: 2px;
  color: var(--brand);
  font-size: 0.82rem;
  letter-spacing: 0.08em;
  text-align: center;
  text-transform: uppercase;
}

.summary-date-picker > span {
  text-align: center;
}

.summary-search-box input {
  width: 100%;
}

.summary-query-field {
  display: grid;
  gap: 6px;
  margin: 0;
}

.summary-query-field span {
  color: var(--muted);
  font-size: 0.72rem;
  font-weight: 900;
  text-align: center;
  text-transform: uppercase;
}

.summary-date-field {
  display: grid;
  gap: 6px;
  margin: 0;
  color: var(--muted);
  font-size: 0.72rem;
  font-weight: 900;
  text-transform: uppercase;
}

.summary-date-field span {
  padding-left: 0;
  text-align: center;
}

.summary-search-box button {
  min-height: 44px;
  padding-inline: 14px;
  border-radius: var(--radius);
  font-size: 0.82rem;
}

.summary-totals {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 8px 0 6px;
}

.summary-totals span {
  padding: 8px 12px;
  border-radius: 999px;
  background: rgba(13, 122, 108, 0.08);
  color: var(--brand);
  font-size: 0.84rem;
  font-weight: 850;
}

.summary-list {
  display: grid;
  gap: 8px;
  max-height: none;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 6px 4px 10px;
  border: 1px solid rgba(15, 23, 42, 0.05);
  border-radius: 20px;
  background: rgba(255, 255, 255, 0.52);
  scrollbar-width: thin;
  scrollbar-color: rgba(13, 122, 108, 0.38) rgba(255, 255, 255, 0.48);
  -webkit-overflow-scrolling: touch;
}

.summary-list::-webkit-scrollbar {
  width: 7px;
}

.summary-list::-webkit-scrollbar-track {
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.48);
}

.summary-list::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: rgba(13, 122, 108, 0.38);
}

.summary-bottom-tools {
  display: grid;
  gap: 10px;
  margin-top: 6px;
  padding: 10px;
  border: 1px solid rgba(15, 23, 42, 0.05);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.58);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.42);
}

.summary-item {
  display: grid;
  grid-template-columns: 34px minmax(0, 1.35fr) minmax(92px, 0.72fr) minmax(112px, 0.78fr);
  gap: 12px;
  align-items: start;
  padding: 14px;
  border: 1px solid rgba(15, 23, 42, 0.05);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.88);
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.54),
    0 12px 22px rgba(15, 23, 42, 0.06);
  cursor: pointer;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
}

.summary-item:focus-visible,
.summary-item:active {
  border-color: rgba(217, 154, 36, 0.74);
  background: #fffaf0;
  outline: 0;
}

.summary-item div {
  min-width: 0;
  display: grid;
  gap: 4px;
}

.summary-item strong,
.summary-item b {
  font-size: 0.92rem;
  line-height: 1.2;
  overflow-wrap: anywhere;
}

.summary-item span {
  color: var(--muted);
  font-size: 0.8rem;
  line-height: 1.25;
  overflow-wrap: anywhere;
}

.summary-item small {
  color: var(--muted);
  font-size: 0.74rem;
  font-weight: 850;
  line-height: 1.25;
  overflow-wrap: anywhere;
}

.summary-main {
  padding-right: 2px;
}

.summary-search-toggle {
  width: 100%;
  min-height: 38px;
  border-radius: 12px;
  font-size: 0.82rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.summary-search-options {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 7px;
}

.summary-search-options button {
  min-height: 36px;
  padding: 7px 9px;
  border: 1px solid rgba(13, 122, 108, 0.15);
  border-radius: 11px;
  background: rgba(239, 248, 244, 0.95);
  color: var(--brand);
  box-shadow: none;
  font-size: 0.72rem;
  line-height: 1.15;
}

.summary-main .summary-data-line {
  display: block;
  margin-top: 3px;
  color: #516a67;
  line-height: 1.35;
}

.summary-main .summary-data-line b {
  color: var(--brand);
  font-weight: 900;
}

.summary-plantonistas {
  justify-items: start;
}

.summary-plantonistas small {
  color: var(--muted);
  font-size: 0.68rem;
  font-weight: 900;
  letter-spacing: 0.08em;
  line-height: 1.1;
  text-transform: uppercase;
}

.summary-history-block {
  grid-column: 2 / -1;
  display: grid !important;
  gap: 4px;
  padding: 8px 10px;
  border-radius: 10px;
}

.summary-history-block strong {
  font-size: 0.72rem;
  font-weight: 950;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.summary-history-block small {
  font-size: 0.7rem;
}

.summary-history-block span {
  font-size: 0.74rem;
  font-weight: 800;
  line-height: 1.3;
  overflow-x: auto;
  padding-bottom: 2px;
  white-space: nowrap;
  -webkit-overflow-scrolling: touch;
}

.summary-observation-block {
  border: 1px solid rgba(217, 154, 36, 0.28);
  background: rgba(255, 247, 237, 0.82);
}

.summary-observation-block strong,
.summary-observation-block small {
  color: #9a5c00 !important;
}

.summary-edit-block {
  border: 1px solid rgba(22, 163, 74, 0.24);
  background: rgba(240, 253, 244, 0.9);
}

.summary-edit-block strong,
.summary-edit-block small {
  color: #15803d !important;
}

.summary-edit-note {
  display: block;
  margin-top: 2px;
  padding-top: 6px;
  border-top: 1px solid rgba(37, 99, 235, 0.16);
  color: #1d4ed8 !important;
  font-size: 0.72rem !important;
  font-weight: 850 !important;
  line-height: 1.25 !important;
}

.summary-edit-entry {
  display: grid;
  gap: 3px;
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px solid rgba(217, 119, 6, 0.24);
}

.summary-edit-entry:first-of-type {
  margin-top: 2px;
  padding-top: 0;
  border-top: 0;
}

.summary-edit-entry div {
  display: flex;
  gap: 6px;
  align-items: flex-start;
}

.summary-edit-entry div span {
  flex: 0 0 auto;
  font-weight: 900;
}

.summary-edit-entry div strong {
  min-width: 0;
  overflow-wrap: anywhere;
}

.summary-new-value {
  color: #d99a24;
  font-weight: 1000;
  background: rgba(217, 154, 36, 0.16);
  border-radius: 6px;
  padding: 1px 4px;
}

.summary-index {
  width: 28px;
  height: 28px;
  display: grid !important;
  place-items: center;
  border-radius: 999px;
  background: linear-gradient(135deg, var(--brand), var(--brand-2));
  color: white;
  font-weight: 850;
  box-shadow: 0 10px 18px rgba(13, 122, 108, 0.2);
}

.summary-item.alert-row {
  border-color: rgba(185, 28, 28, 0.34);
  background: var(--danger-bg);
  color: var(--danger);
}

.summary-item.alert-row span,
.summary-item.alert-row b,
.summary-item.alert-row strong {
  color: var(--danger);
}

.summary-item.edited-row {
  border-color: rgba(22, 163, 74, 0.48);
  background: linear-gradient(135deg, #f0fdf4 0%, #f7fee7 100%);
}

.summary-item.edited-row .summary-index {
  background: #15803d;
}

.summary-item.edited-row.alert-row {
  border-color: rgba(22, 163, 74, 0.55);
  background: linear-gradient(135deg, #ecfdf5 0%, #fff7ed 100%);
}

.daily-table-card {
  border-radius: 18px;
  box-shadow:
    0 14px 26px rgba(13, 50, 87, 0.08),
    inset 0 0 0 1px rgba(255, 255, 255, 0.48);
}

.daily-tone-a {
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.98), rgba(239, 248, 244, 0.94));
}

.daily-tone-b {
  background: linear-gradient(135deg, rgba(250, 252, 255, 0.98), rgba(234, 243, 250, 0.92));
}

.daily-tone-c {
  background: linear-gradient(135deg, rgba(255, 251, 244, 0.98), rgba(247, 237, 224, 0.94));
}

.daily-tone-d {
  background: linear-gradient(135deg, rgba(247, 246, 255, 0.98), rgba(234, 237, 249, 0.94));
}

.empty-state {
  margin: 0;
  padding: 18px;
  border: 1px dashed rgba(13, 122, 108, 0.2);
  border-radius: 18px;
  color: var(--muted);
  background: rgba(255, 255, 255, 0.62);
}

.edit-context {
  margin: 0 0 12px;
  padding: 10px 12px;
  border-radius: var(--radius);
  background: #e7efe9;
  color: var(--brand);
  font-size: 0.84rem;
  font-weight: 900;
  line-height: 1.35;
}

@media (min-width: 960px) {
  .layout {
    grid-template-columns: 1fr 1fr;
    align-items: start;
  }

  .summary-panel,
  .settings-panel {
    grid-column: 1 / -1;
  }
}

@keyframes panel-arrival {
  from {
    opacity: 0;
    transform: translateY(10px) scale(0.985);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@media (max-width: 680px) {
  .app-shell {
    width: min(100% - 12px, 100%);
    padding-top: 4px;
  }

  .topbar {
    display: grid;
    grid-template-columns: minmax(102px, auto) minmax(0, 1fr) minmax(64px, auto);
    justify-items: stretch;
    gap: 3px 6px;
    padding: 18px 12px;
  }

  .topbar-status {
    grid-column: 3;
    grid-row: 1;
    width: 100%;
    min-width: min(64px, 16vw);
    justify-content: flex-end;
  }

  .home-logo-link {
    width: 102px;
    height: 102px;
  }

  .hero-copy {
    display: grid;
    justify-items: center;
    text-align: center;
  }

  .panel {
    padding: 12px;
    border-radius: 18px;
  }

  .scanner-panel {
    margin: 4px 0 7px;
  }

  .topbar .hero-copy > [data-auth-user] {
    font-size: 0.72rem;
  }

  .scanner-panel .actions button,
  .scanner-panel .wide-button,
  .home-action-button {
    min-height: 39px;
    padding: 7px 10px;
    font-size: 0.8rem;
  }

  .scanner-panel .scanner-actions {
    gap: 8px;
    margin-top: 8px;
  }

  .scanner-panel .capture-shutter {
    flex: 1 1 100%;
    width: 100%;
    height: auto;
    min-height: 54px;
    padding: 9px 16px;
    border-width: 2px;
    font-size: 0.82rem;
  }

  .scanner-panel video {
    min-height: clamp(205px, 31dvh, 250px);
    max-height: 250px;
  }

  .camera-stage {
    min-height: clamp(205px, 31dvh, 250px);
  }

  .guide-frame {
    width: calc(100% - 24px);
    max-width: calc(100% - 24px);
    height: auto;
    min-height: 0;
    aspect-ratio: 4 / 1;
  }

  .scanner-panel #preview.has-image {
    max-height: 96px;
    margin-top: 6px;
  }

  .scanner-panel .preview-wrap {
    max-height: 100px;
    overflow: hidden;
  }

  .capture-note {
    margin-top: 5px;
    padding: 6px 8px 6px 28px;
    font-size: 0.7rem;
  }

  .modal-panel {
    width: calc(100% - 8px);
    max-height: calc(100dvh - 8px);
    padding: 10px;
  }

  .summary-panel.modal-panel {
    max-height: calc(100dvh - 8px);
    padding: 10px;
  }

  .summary-panel .section-title {
    margin-bottom: 4px;
    padding: 3px 5px;
  }

  .monthly-panel .section-title {
    margin-bottom: 4px;
    padding: 3px 5px;
  }

  .summary-panel .section-title-copy > [data-auth-user],
  .monthly-panel .section-title-copy > [data-auth-user] {
    font-size: 0.64rem;
  }

  .monthly-heading {
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 5px;
    margin-bottom: 5px;
  }

  .monthly-heading h2 {
    font-size: 0.86rem;
  }

  .monthly-month-control {
    grid-column: 1 / -1;
    grid-row: 2;
    grid-template-columns: auto minmax(0, 1fr);
    min-height: 32px;
    padding: 3px 6px;
  }

  .summary-panel .summary-bottom-tools {
    margin-top: 4px;
    padding: 8px;
  }

  .summary-panel .summary-totals {
    margin: 6px 0 4px;
  }

  .summary-panel .summary-list {
    max-height: none;
    min-height: 0;
    padding: 3px 3px 8px;
  }

  .monthly-report-panel {
    gap: 7px;
    margin-top: 4px;
    padding: 7px;
  }

  .form-panel.modal-panel {
    width: calc(100% - 8px);
    max-height: calc(100dvh - 8px);
    padding: 8px;
