#entry-panel.manual-entry-expanded #plantonistas-options{grid-template-columns:repeat(5,minmax(0,1fr))!important;grid-auto-rows:36px!important;height:252px!important;max-height:252px!important;gap:5px!important;padding:6px!important;overflow:hidden!important}
#entry-panel.manual-entry-expanded #plantonistas-options label{display:flex!important;align-items:center!important;justify-content:center!important;min-height:36px!important;height:36px!important;padding:5px 3px!important;border-radius:10px!important;font-size:.72rem!important;font-weight:900!important;line-height:1!important;text-align:center!important}
#entry-panel.manual-entry-expanded #plantonistas-options input{width:18px!important;height:18px!important;margin:0 4px 0 0!important}
@media(max-width:680px){
  #entry-panel.manual-entry-expanded #label-form{grid-template-rows:repeat(5,minmax(38px,1fr)) minmax(0,252px)!important}
  #entry-panel.manual-entry-expanded #plantonistas-options{height:252px!important;max-height:252px!important;grid-auto-rows:36px!important;gap:5px!important}
  #entry-panel.manual-entry-expanded #plantonistas-options label{min-height:36px!important;height:36px!important;font-size:.7rem!important}
}

/* Relatório mensal: o rodapé é uma linha própria do modal e não pode ser
   coberto pela lista ou pelo botão de geração do relatório. */
#monthly-panel.is-open{display:grid!important;grid-template-rows:auto auto minmax(0,1fr) auto!important;align-content:stretch!important;min-height:0!important;height:95dvh!important;max-height:95dvh!important;overflow:hidden!important;box-sizing:border-box!important}
#monthly-panel.is-open .monthly-report-panel{display:grid!important;grid-template-rows:auto minmax(0,1fr) auto!important;flex:1 1 auto!important;min-height:0!important;height:auto!important;overflow:hidden!important}
#monthly-panel.is-open .monthly-list{min-height:0!important;height:auto!important;max-height:none!important;overflow-y:auto!important;overflow-x:hidden!important}
#monthly-panel.is-open>.panel-base-action{display:flex!important;flex:0 0 auto!important;min-height:50px!important;align-items:center!important;justify-content:center!important;margin:8px 0 0!important;padding:8px 0 max(8px,env(safe-area-inset-bottom,0px))!important;border-top:1px solid rgba(13,50,87,.1)!important;z-index:5!important;background:linear-gradient(180deg,rgba(237,227,207,.4),rgba(237,227,207,.98))!important}
#monthly-panel.is-open>.panel-base-action .panel-home-button{display:flex!important;align-items:center!important;justify-content:center!important;text-align:center!important;min-height:42px!important}

/* iOS: controles menores que 16px provocam zoom automático ao tocar. */
@media(max-width:640px){
  #edit-overlay.edit-overlay{touch-action:manipulation!important;-webkit-text-size-adjust:100%!important}
  #edit-overlay.edit-overlay .edit-card{transform:translate3d(0,0,0)!important;touch-action:manipulation!important}
  #edit-overlay.edit-overlay #edit-summary .confirm-edit-grid input,
  #edit-overlay.edit-overlay #edit-summary .confirm-edit-grid select,
  #edit-overlay.edit-overlay #edit-summary .confirm-edit-grid textarea{font-size:16px!important;-webkit-text-size-adjust:100%!important}
}

/* Entrada manual e leitura: compactar apenas os títulos dos campos para
   transferir altura real à grade de Plantonista(s). Os controles continuam
   com área de toque confortável e todas as 39 siglas permanecem no bloco. */
#entry-panel.manual-entry-expanded #label-form {
  grid-template-rows: repeat(5, minmax(31px, auto)) minmax(0, 276px) minmax(31px, auto) !important;
  row-gap: 3px !important;
}

#entry-panel.manual-entry-expanded #label-form > label:not(:has(#plantonistas-picker)) {
  min-height: 31px !important;
  padding: 2px 4px !important;
  gap: 0 !important;
  justify-content: center !important;
}

#entry-panel.manual-entry-expanded #label-form > label:not(:has(#plantonistas-picker)) > span {
  min-height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  font-size: .62rem !important;
  line-height: 1.1 !important;
}

#entry-panel.manual-entry-expanded #label-form > label:not(:has(#plantonistas-picker)) > input,
#entry-panel.manual-entry-expanded #label-form > label:not(:has(#plantonistas-picker)) > select {
  min-height: 33px !important;
  height: 33px !important;
  padding: 4px 7px !important;
}

#entry-panel.manual-entry-expanded #label-form > label:has(#plantonistas-picker) {
  min-height: 272px !important;
  height: 272px !important;
}

#entry-panel.manual-entry-expanded #plantonistas-picker,
#entry-panel.manual-entry-expanded #plantonistas-options {
  min-height: 272px !important;
  height: 272px !important;
  max-height: 272px !important;
}

#entry-panel.manual-entry-expanded #plantonistas-options {
  grid-template-columns: repeat(6, minmax(0, 1fr)) !important;
  grid-template-rows: repeat(7, 34px) !important;
  grid-auto-rows: 34px !important;
  gap: 4px !important;
  padding: 5px !important;
  overflow: visible !important;
}

#entry-panel.manual-entry-expanded #plantonistas-options label {
  min-height: 34px !important;
  height: auto !important;
  padding: 4px 1px !important;
  font-size: .68rem !important;
  line-height: 1 !important;
  white-space: nowrap !important;
}

#entry-panel.manual-entry-expanded #plantonistas-options input {
  width: 15px !important;
  height: 15px !important;
  flex: 0 0 15px !important;
  margin-right: 3px !important;
}

/* Ajuste final de entrada: havia área livre depois da grade e no rodapé do
   bloco de Plantonista(s). Aumentamos os campos e os alvos de toque sem
   criar rolagem nem alterar a quantidade de siglas exibidas. */
#entry-panel.manual-entry-expanded #label-form {
  grid-template-rows: repeat(5, minmax(37px, auto)) minmax(0, 304px) minmax(37px, auto) !important;
  row-gap: 4px !important;
}

#entry-panel.manual-entry-expanded #label-form > label:not(:has(#plantonistas-picker)) {
  min-height: 37px !important;
  padding: 3px 5px !important;
}

#entry-panel.manual-entry-expanded #label-form > label:not(:has(#plantonistas-picker)) > span {
  font-size: .68rem !important;
  line-height: 1.1 !important;
}

#entry-panel.manual-entry-expanded #label-form > label:not(:has(#plantonistas-picker)) > input,
#entry-panel.manual-entry-expanded #label-form > label:not(:has(#plantonistas-picker)) > select {
  min-height: 39px !important;
  height: 39px !important;
  padding: 5px 8px !important;
}

#entry-panel.manual-entry-expanded #label-form > label:has(#plantonistas-picker),
#entry-panel.manual-entry-expanded #plantonistas-picker,
#entry-panel.manual-entry-expanded #plantonistas-options {
  min-height: 300px !important;
  height: 300px !important;
  max-height: 300px !important;
}

#entry-panel.manual-entry-expanded #plantonistas-options {
  grid-template-rows: repeat(7, 38px) !important;
  grid-auto-rows: 38px !important;
  gap: 5px !important;
  padding: 6px !important;
}

#entry-panel.manual-entry-expanded #plantonistas-options label {
  min-height: 38px !important;
  height: 38px !important;
  padding: 5px 2px !important;
  font-size: .72rem !important;
}

#entry-panel.manual-entry-expanded #plantonistas-options input {
  width: 17px !important;
  height: 17px !important;
  flex-basis: 17px !important;
  margin-right: 4px !important;
}

/* Acabamento final do bloco de siglas e dos comandos da entrada. A grade
   fica contida dentro do cartão de Plantonista(s); o espaço inferior passa
   a ser usado pelos botões, sem deixar a grade vazar sobre o fundo. */
#entry-panel.manual-entry-expanded #label-form > label:has(#plantonistas-picker),
#entry-panel.manual-entry-expanded #plantonistas-picker {
  box-sizing: border-box !important;
  overflow: hidden !important;
  border-radius: 14px !important;
}

#entry-panel.manual-entry-expanded #plantonistas-options {
  box-sizing: border-box !important;
  grid-template-rows: repeat(7, 36px) !important;
  grid-auto-rows: 36px !important;
  gap: 4px !important;
  padding: 6px !important;
  overflow: hidden !important;
  align-content: start !important;
  border-radius: 12px !important;
}

#entry-panel.manual-entry-expanded #plantonistas-options label {
  box-sizing: border-box !important;
  min-height: 36px !important;
  height: 36px !important;
  padding: 4px 2px !important;
  border-radius: 10px !important;
}

#entry-panel.manual-entry-expanded > .actions {
  gap: 10px !important;
  margin-top: 2px !important;
  padding: 10px 0 6px !important;
}

#entry-panel.manual-entry-expanded > .actions > button {
  min-height: 58px !important;
  padding: 13px 12px !important;
  border-radius: 18px !important;
  font-size: .78rem !important;
  letter-spacing: .06em !important;
  position: relative !important;
  isolation: isolate !important;
  overflow: hidden !important;
  transform: translateY(0) !important;
  transition: transform 160ms ease, box-shadow 160ms ease, filter 160ms ease !important;
}

#entry-panel.manual-entry-expanded > .actions > button::before {
  content: "" !important;
  position: absolute !important;
  z-index: -1 !important;
  inset: 2px 10% auto !important;
  height: 42% !important;
  border-radius: 999px !important;
  background: linear-gradient(180deg, rgba(255,255,255,.72), rgba(255,255,255,0)) !important;
  pointer-events: none !important;
}

#entry-panel.manual-entry-expanded > .actions > #send-sheet {
  background:
    radial-gradient(circle at 18% 0%, rgba(255,255,255,.7), transparent 32%),
    linear-gradient(145deg, #2f87c9 0%, #1762a1 48%, #0d3257 100%) !important;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.95),
    inset 0 -6px 10px rgba(5,35,70,.25),
    0 5px 0 rgba(8,50,92,.42),
    0 16px 24px rgba(13,50,87,.24) !important;
}

#entry-panel.manual-entry-expanded > .actions > #clear-form {
  background:
    radial-gradient(circle at 18% 0%, rgba(255,255,255,.86), transparent 34%),
    linear-gradient(145deg, #ffffff 0%, #e8f1f5 48%, #b9ced8 100%) !important;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.98),
    inset 0 -6px 10px rgba(48,87,105,.13),
    0 5px 0 rgba(104,137,151,.42),
    0 16px 24px rgba(20,58,78,.18) !important;
}

#entry-panel.manual-entry-expanded > .actions > button:active {
  transform: translateY(4px) scale(.985) !important;
  box-shadow: 0 1px 0 rgba(20,58,78,.34), inset 0 3px 8px rgba(20,58,78,.16) !important;
}

/* Correção final: o bloco de siglas permanece dentro do fluxo do formulário
   e não cobre o campo Valor. O formulário pode rolar internamente no modal. */
@media (max-width: 680px) {
  #entry-panel.manual-entry-expanded #label-form {
    grid-template-rows: none !important;
    grid-auto-rows: minmax(37px, auto) !important;
    align-content: start !important;
    overflow-y: auto !important;
    overflow-x: hidden !important;
    -webkit-overflow-scrolling: touch;
  }

  #entry-panel.manual-entry-expanded #label-form > label:has(#plantonistas-picker) {
    grid-column: 1 / -1 !important;
    grid-row: auto !important;
    height: auto !important;
    min-height: 0 !important;
    overflow: visible !important;
  }

  #entry-panel.manual-entry-expanded #valor-field {
    grid-column: auto !important;
    grid-row: auto !important;
    position: static !important;
    z-index: auto !important;
  }

  #entry-panel.manual-entry-expanded #plantonistas-picker,
  #entry-panel.manual-entry-expanded #plantonistas-options {
    height: auto !important;
    min-height: 0 !important;
    max-height: 220px !important;
    overflow-y: auto !important;
    overflow-x: hidden !important;
  }

  #entry-panel.manual-entry-expanded #plantonistas-options {
    grid-template-rows: none !important;
    grid-auto-rows: minmax(31px, auto) !important;
  }
}

/* Ajuste do modal de entrada: plantonistas fixos e faixa decorativa do valor. */
